//! Internationalized domain names (spec §16.2 `AI_IDN`, `AI_CANONIDN`, `NI_IDN`; D-16.4): UTS #46
//! processing with the Unicode 15.1.0 tables (`idna_tables`, generated by `cargo xtask
//! unicode-gen`) and Punycode (RFC 3492). Built in: nothing is loaded at run time.
//!
//! **Options** (UTS #46 §4, chosen from the probes of the reference, D-16.4): nontransitional
//! processing (deviations such as `ß` are kept: `faß` is `xn--fa-hia`); CheckHyphens (no `-`
//! first or last, none in positions 3 and 4); CheckBidi (RFC 5893, all six rules, for a domain
//! name with a right-to-left label); CheckJoiners (RFC 5892 Appendix A.1 and A.2); no
//! UseSTD3ASCIIRules (`_` and other ASCII are kept, as the reference keeps them); and, beyond
//! UTS #46, the code points IDNA2008 excludes (`NV8`, `XV8`: symbols and emoji) are refused, as
//! the reference refuses them. An encoded label longer than 63 bytes is an error; empty labels
//! are kept (the DNS layer then refuses the name).
//!
//! **To Unicode** ([`to_unicode`], `NI_IDN`, `AI_CANONIDN`; observed): each label that starts
//! with `xn--` (any case) and decodes to a label that is not all ASCII is replaced by the decoded
//! code points (the case of its ASCII letters kept); any other label is kept as it is.

use crate::error::{Errno, Result};
use crate::mem::TryVec;

use super::idna_tables::{
    COMPOSE, DECOMP_DATA, DECOMP_END, DECOMP_KEY, MAP_ARG, MAP_LEN, MAP_POOL, MAP_START, MAX_MAP, PALETTE, SHIFT, TRIE1,
    TRIE2,
};

const BAD: Errno = Errno::EILSEQ;

const VALID: u8 = 0;
const IGNORED: u8 = 1;
const MAPPED: u8 = 2;
const DEVIATION: u8 = 3;
const STD3_VALID: u8 = 5;
const STD3_MAPPED: u8 = 6;
const EXCLUDED: u8 = 0x10;

/// The property word of `c`: `status | excluded << 4 | bidi << 5 | joining << 9 | mark << 12` (one
/// two-level trie lookup; code points past U+10FFFF share the last code point's word).
fn props(c: u32) -> u16 {
    let c = usize::try_from(c.min(0x10_ffff)).unwrap_or(0);
    let block = TRIE1.get(c >> SHIFT).map_or(0, |&b| usize::from(b));
    let idx = block << SHIFT | (c & ((1 << SHIFT) - 1));
    PALETTE.get(TRIE2.get(idx).map_or(0, |&i| usize::from(i))).copied().unwrap_or(4)
}

/// The UTS #46 status of `c` (low bits, `EXCLUDED` when IDNA2008 excludes it).
fn status(c: u32) -> u8 {
    u8::try_from(props(c) & 0x1f).unwrap_or(4)
}

/// The mapping of a code point: at most `MAX_MAP` code points, empty when it has none.
struct Mapped {
    buf: [u32; MAX_MAP],
    len: usize,
}

impl core::ops::Deref for Mapped {
    type Target = [u32];
    fn deref(&self) -> &[u32] {
        self.buf.get(..self.len).unwrap_or(&[])
    }
}

/// The mapping of `c` (the mapped, STD3-mapped and deviation code points have one).
fn mapping(c: u32) -> Mapped {
    let mut m = Mapped { buf: [0; MAX_MAP], len: 0 };
    let i = MAP_START.partition_point(|&s| s <= c);
    let Some(i) = i.checked_sub(1) else { return m };
    let (Some(&start), Some(&run), Some(&arg)) = (MAP_START.get(i), MAP_LEN.get(i), MAP_ARG.get(i)) else { return m };
    if run != 0 {
        if c.saturating_sub(start) < u32::from(run) {
            if let Some(d) = m.buf.first_mut() {
                *d = c.wrapping_add(arg);
                m.len = 1;
            }
        }
    } else if c == start {
        let off = usize::try_from(arg >> 8).unwrap_or(0);
        let len = usize::try_from(arg & 0xff).unwrap_or(0);
        for (d, s) in m.buf.iter_mut().zip(MAP_POOL.get(off..off.saturating_add(len)).unwrap_or(&[])) {
            *d = *s;
        }
        m.len = len.min(MAX_MAP);
    }
    m
}

fn bidi_of(c: u32) -> u8 {
    u8::try_from(props(c) >> 5 & 0xf).unwrap_or(0)
}

fn joining_of(c: u32) -> u8 {
    u8::try_from(props(c) >> 9 & 0x7).unwrap_or(0)
}

fn is_mark(c: u32) -> bool {
    props(c) >> 12 & 1 == 1
}

fn ccc(c: u32) -> u8 {
    crate::unicode::combining_class(c)
}

// ------------------------------------------------------------------------------ NFC

const S_BASE: u32 = 0xac00;
const L_BASE: u32 = 0x1100;
const V_BASE: u32 = 0x1161;
const T_BASE: u32 = 0x11a7;
const L_COUNT: u32 = 19;
const V_COUNT: u32 = 21;
const T_COUNT: u32 = 28;
const N_COUNT: u32 = V_COUNT * T_COUNT;
const S_COUNT: u32 = L_COUNT * N_COUNT;

/// Canonical decomposition of `c` appended to `out` (Hangul algorithmically).
fn decompose(c: u32, out: &mut TryVec<u32>) -> Result<()> {
    if let Some(s) = c.checked_sub(S_BASE).filter(|&s| s < S_COUNT) {
        out.push(L_BASE.saturating_add(s / N_COUNT))?;
        out.push(V_BASE.saturating_add(s % N_COUNT / T_COUNT))?;
        let t = s % T_COUNT;
        if t != 0 {
            out.push(T_BASE.saturating_add(t))?;
        }
        return Ok(());
    }
    match DECOMP_KEY.binary_search(&c) {
        Ok(i) => {
            let end = DECOMP_END.get(i).map_or(0, |&e| usize::from(e));
            let start = i.checked_sub(1).and_then(|p| DECOMP_END.get(p)).map_or(0, |&e| usize::from(e));
            out.extend_from_slice(DECOMP_DATA.get(start..end).unwrap_or(&[]))
        }
        Err(_) => out.push(c),
    }
}

fn compose_pair(a: u32, b: u32) -> Option<u32> {
    if let Some(l) = a.checked_sub(L_BASE).filter(|&l| l < L_COUNT) {
        if let Some(v) = b.checked_sub(V_BASE).filter(|&v| v < V_COUNT) {
            return Some(S_BASE.saturating_add(l.saturating_mul(N_COUNT)).saturating_add(v.saturating_mul(T_COUNT)));
        }
    }
    if let Some(s) = a.checked_sub(S_BASE).filter(|&s| s < S_COUNT && s % T_COUNT == 0) {
        if let Some(t) = b.checked_sub(T_BASE).filter(|&t| t > 0 && t < T_COUNT) {
            return Some(S_BASE.saturating_add(s).saturating_add(t));
        }
    }
    if a >= 1 << 21 || b >= 1 << 21 {
        return None;
    }
    let key = u64::from(a) << 21 | u64::from(b);
    COMPOSE.binary_search_by(|e| (e >> 21).cmp(&key)).ok().and_then(|i| COMPOSE.get(i)).and_then(|e| u32::try_from(e & 0x1f_ffff).ok())
}

/// Normalization Form C of `input`.
pub fn nfc(input: &[u32]) -> Result<TryVec<u32>> {
    let mut d = TryVec::new();
    for &c in input {
        decompose(c, &mut d)?;
    }
    // Canonical ordering: a stable sort of each run of non-starters by combining class.
    let s = d.as_mut_slice();
    let mut i = 0usize;
    while i < s.len() {
        if s.get(i).is_some_and(|&c| ccc(c) != 0) {
            let start = i;
            while s.get(i).is_some_and(|&c| ccc(c) != 0) {
                i = i.saturating_add(1);
            }
            if let Some(run) = s.get_mut(start..i) {
                run.sort_by_key(|&c| ccc(c));
            }
        } else {
            i = i.saturating_add(1);
        }
    }
    // Canonical composition.
    let mut out: TryVec<u32> = TryVec::new();
    let mut starter: Option<usize> = None;
    let mut last_cc: Option<u8> = None;
    for &c in d.iter() {
        let cc = ccc(c);
        if let Some(si) = starter {
            let blocked = last_cc.is_some_and(|l| l == 0 || l >= cc);
            if !blocked {
                if let Some(comp) = out.get(si).and_then(|&s| compose_pair(s, c)) {
                    if let Some(slot) = out.get_mut(si) {
                        *slot = comp;
                    }
                    continue;
                }
            }
        }
        if cc == 0 {
            starter = Some(out.len());
            last_cc = None;
        } else {
            last_cc = Some(cc);
        }
        out.push(c)?;
    }
    Ok(out)
}

// ------------------------------------------------------------------------------ Punycode

const BASE: u32 = 36;
const TMIN: u32 = 1;
const TMAX: u32 = 26;
const SKEW: u32 = 38;
const DAMP: u32 = 700;

fn adapt(delta: u32, points: u32, first: bool) -> u32 {
    let mut d = if first { delta / DAMP } else { delta / 2 };
    d = d.saturating_add(d.checked_div(points).unwrap_or(0));
    let mut k = 0u32;
    while d > (BASE - TMIN) * TMAX / 2 {
        d /= BASE - TMIN;
        k = k.saturating_add(BASE);
    }
    k.saturating_add((BASE - TMIN + 1).saturating_mul(d).checked_div(d.saturating_add(SKEW)).unwrap_or(0))
}

fn threshold(k: u32, bias: u32) -> u32 {
    if k <= bias {
        TMIN
    } else if k >= bias.saturating_add(TMAX) {
        TMAX
    } else {
        k.saturating_sub(bias)
    }
}

fn digit(d: u32) -> u8 {
    let d = u8::try_from(d).unwrap_or(0);
    if d < 26 { b'a'.saturating_add(d) } else { b'0'.saturating_add(d.saturating_sub(26)) }
}

/// The Punycode of `input` (RFC 3492 §6.3), appended to `out`.
pub fn punycode_encode(input: &[u32], out: &mut TryVec<u8>) -> Result<()> {
    let mut b = 0u32;
    for &c in input {
        if c < 0x80 {
            out.push(u8::try_from(c).map_err(|_| BAD)?)?;
            b = b.saturating_add(1);
        }
    }
    let mut h = b;
    if b > 0 {
        out.push(b'-')?;
    }
    let total = u32::try_from(input.len()).map_err(|_| BAD)?;
    let (mut n, mut delta, mut bias) = (0x80u32, 0u32, 72u32);
    while h < total {
        let m = input.iter().copied().filter(|&c| c >= n).min().ok_or(BAD)?;
        delta = delta.checked_add(m.checked_sub(n).ok_or(BAD)?.checked_mul(h.checked_add(1).ok_or(BAD)?).ok_or(BAD)?).ok_or(BAD)?;
        n = m;
        for &c in input {
            if c < n {
                delta = delta.checked_add(1).ok_or(BAD)?;
            }
            if c == n {
                let mut q = delta;
                let mut k = BASE;
                loop {
                    let t = threshold(k, bias);
                    if q < t {
                        break;
                    }
                    let span = BASE.saturating_sub(t);
                    out.push(digit(t.saturating_add(q.saturating_sub(t).checked_rem(span).unwrap_or(0))))?;
                    q = q.saturating_sub(t).checked_div(span).unwrap_or(0);
                    k = k.checked_add(BASE).ok_or(BAD)?;
                }
                out.push(digit(q))?;
                bias = adapt(delta, h.saturating_add(1), h == b);
                delta = 0;
                h = h.saturating_add(1);
            }
        }
        delta = delta.checked_add(1).ok_or(BAD)?;
        n = n.checked_add(1).ok_or(BAD)?;
    }
    Ok(())
}

fn digit_value(c: u8) -> Option<u32> {
    match c {
        b'a'..=b'z' => Some(u32::from(c.wrapping_sub(b'a'))),
        b'A'..=b'Z' => Some(u32::from(c.wrapping_sub(b'A'))),
        b'0'..=b'9' => Some(u32::from(c.wrapping_sub(b'0')).saturating_add(26)),
        _ => None,
    }
}

/// The code points the Punycode `input` stands for (RFC 3492 §6.2).
pub fn punycode_decode(input: &[u8]) -> Result<TryVec<u32>> {
    let mut out: TryVec<u32> = TryVec::new();
    let (basic, rest) = match input.iter().rposition(|&c| c == b'-') {
        Some(p) => (input.get(..p).unwrap_or(&[]), input.get(p.saturating_add(1)..).unwrap_or(&[])),
        None => (&[][..], input),
    };
    for &c in basic {
        if c >= 0x80 {
            return Err(BAD);
        }
        out.push(u32::from(c))?;
    }
    let (mut n, mut i, mut bias) = (0x80u32, 0u32, 72u32);
    let mut pos = 0usize;
    while pos < rest.len() {
        let old = i;
        let mut w = 1u32;
        let mut k = BASE;
        loop {
            let d = digit_value(*rest.get(pos).ok_or(BAD)?).ok_or(BAD)?;
            pos = pos.saturating_add(1);
            i = i.checked_add(d.checked_mul(w).ok_or(BAD)?).ok_or(BAD)?;
            let t = threshold(k, bias);
            if d < t {
                break;
            }
            w = w.checked_mul(BASE.saturating_sub(t)).ok_or(BAD)?;
            k = k.checked_add(BASE).ok_or(BAD)?;
        }
        let len = u32::try_from(out.len()).map_err(|_| BAD)?.checked_add(1).ok_or(BAD)?;
        bias = adapt(i.saturating_sub(old), len, old == 0);
        n = n.checked_add(i.checked_div(len).ok_or(BAD)?).ok_or(BAD)?;
        i = i.checked_rem(len).ok_or(BAD)?;
        if n > 0x10_ffff || (0xd800..=0xdfff).contains(&n) {
            return Err(BAD);
        }
        out.insert(usize::try_from(i).map_err(|_| BAD)?, n)?;
        i = i.saturating_add(1);
    }
    Ok(out)
}

// ------------------------------------------------------------------------------ validity

fn starts_xn(label: &[u32]) -> bool {
    match label {
        [x, n, h1, h2, ..] => (*x | 0x20) == u32::from(b'x') && (*n | 0x20) == u32::from(b'n') && *h1 == u32::from(b'-') && *h2 == u32::from(b'-'),
        _ => false,
    }
}

const L: u8 = 0;
const R: u8 = 1;
const AL: u8 = 2;
const EN: u8 = 3;
const ES: u8 = 4;
const ET: u8 = 5;
const AN: u8 = 6;
const CS: u8 = 7;
const NSM: u8 = 8;
const BN: u8 = 9;
const ON: u8 = 10;

fn bidi(c: u32) -> u8 {
    bidi_of(c)
}

/// RFC 5893 §2 for one label of a Bidi domain name.
fn bidi_ok(label: &[u32]) -> bool {
    let Some(&first) = label.first() else { return true };
    let classes = || label.iter().map(|&c| bidi(c));
    let last_strong = || label.iter().rev().map(|&c| bidi(c)).find(|&b| b != NSM);
    match bidi(first) {
        R | AL => {
            classes().all(|b| matches!(b, R | AL | AN | EN | ES | CS | ET | ON | BN | NSM))
                && matches!(last_strong(), Some(R | AL | EN | AN))
                && !(classes().any(|b| b == EN) && classes().any(|b| b == AN))
        }
        L => classes().all(|b| matches!(b, L | EN | ES | CS | ET | ON | BN | NSM)) && matches!(last_strong(), Some(L | EN)),
        _ => false,
    }
}

const ZWNJ: u32 = 0x200c;
const ZWJ: u32 = 0x200d;

/// RFC 5892 Appendix A.1 and A.2 (CONTEXTJ).
fn joiners_ok(label: &[u32]) -> bool {
    for (i, &c) in label.iter().enumerate() {
        if c != ZWNJ && c != ZWJ {
            continue;
        }
        if i > 0 && label.get(i.saturating_sub(1)).is_some_and(|&p| ccc(p) == 9) {
            continue;
        }
        if c == ZWJ {
            return false;
        }
        let jt = joining_of;
        let before = label.get(..i).unwrap_or(&[]).iter().rev().map(|&x| jt(x)).find(|&t| t != 1);
        let after = label.get(i.saturating_add(1)..).unwrap_or(&[]).iter().map(|&x| jt(x)).find(|&t| t != 1);
        if !(matches!(before, Some(2 | 4)) && matches!(after, Some(3 | 4))) {
            return false;
        }
    }
    true
}

/// UTS #46 §4.1 for one label (Bidi is checked over the whole name).
fn label_ok(label: &[u32]) -> Result<bool> {
    if label.is_empty() {
        return Ok(true);
    }
    if nfc(label)?.as_slice() != label {
        return Ok(false);
    }
    let hy = u32::from(b'-');
    if label.get(2) == Some(&hy) && label.get(3) == Some(&hy) {
        return Ok(false);
    }
    if label.first() == Some(&hy) || label.last() == Some(&hy) {
        return Ok(false);
    }
    if label.first().is_some_and(|&c| is_mark(c)) {
        return Ok(false);
    }
    for &c in label {
        let s = status(c);
        if s & EXCLUDED != 0 || !matches!(s & 0xf, VALID | DEVIATION | STD3_VALID) || c == u32::from(b'.') {
            return Ok(false);
        }
    }
    Ok(joiners_ok(label))
}

/// UTS #46 ToASCII of the code points `input` (see the module documentation), appended to
/// `out`. `EILSEQ` when the name is not valid.
pub fn to_ascii(input: &[u32], out: &mut TryVec<u8>) -> Result<()> {
    let mut mapped: TryVec<u32> = TryVec::new();
    for &c in input {
        let s = status(c);
        match s & 0xf {
            VALID | DEVIATION | STD3_VALID => mapped.push(c)?,
            IGNORED => {}
            MAPPED | STD3_MAPPED => mapped.extend_from_slice(&mapping(c))?,
            _ => return Err(BAD),
        }
    }
    let norm = nfc(&mapped)?;
    let dot = u32::from(b'.');
    let mut labels: TryVec<TryVec<u32>> = TryVec::new();
    for raw in norm.split(|&c| c == dot) {
        let label = if starts_xn(raw) {
            let mut ascii: TryVec<u8> = TryVec::new();
            for &c in raw.get(4..).unwrap_or(&[]) {
                ascii.push(u8::try_from(c).map_err(|_| BAD)?)?;
            }
            let d = punycode_decode(&ascii)?;
            if d.iter().all(|&c| c < 0x80) {
                return Err(BAD);
            }
            d
        } else {
            TryVec::from_slice(raw)?
        };
        if !label_ok(&label)? {
            return Err(BAD);
        }
        labels.push(label)?;
    }
    let bidi_name = labels.iter().any(|l| l.iter().any(|&c| matches!(bidi(c), R | AL | AN)));
    if bidi_name && !labels.iter().all(|l| bidi_ok(l)) {
        return Err(BAD);
    }
    for (i, (label, raw)) in labels.iter().zip(norm.split(|&c| c == dot)).enumerate() {
        if i > 0 {
            out.push(b'.')?;
        }
        let start = out.len();
        if raw.iter().all(|&c| c < 0x80) {
            for &c in raw {
                out.push(u8::try_from(c).map_err(|_| BAD)?)?;
            }
        } else {
            out.extend_from_slice(b"xn--")?;
            punycode_encode(label, out)?;
        }
        if out.len().saturating_sub(start) > 63 {
            return Err(BAD);
        }
    }
    Ok(())
}

/// ToUnicode as `NI_IDN` and `AI_CANONIDN` apply it (see the module documentation): the code
/// points, appended to `out`.
pub fn to_unicode(name: &[u8], out: &mut TryVec<u32>) -> Result<()> {
    for (i, label) in name.split(|&c| c == b'.').enumerate() {
        if i > 0 {
            out.push(u32::from(b'.'))?;
        }
        let decoded = match label.get(..4) {
            Some(p) if p.eq_ignore_ascii_case(b"xn--") => punycode_decode(label.get(4..).unwrap_or(&[])).ok().filter(|d| d.iter().any(|&c| c >= 0x80)),
            _ => None,
        };
        match decoded {
            Some(d) => out.extend_from_slice(&d)?,
            None => {
                for &b in label {
                    out.push(u32::from(b))?;
                }
            }
        }
    }
    Ok(())
}

#[cfg(test)]
#[allow(clippy::unwrap_used, clippy::indexing_slicing, clippy::panic)]
mod tests {
    use super::*;

    fn ascii(s: &str) -> core::result::Result<alloc::string::String, Errno> {
        let cps: alloc::vec::Vec<u32> = s.chars().map(u32::from).collect();
        let mut out = TryVec::new();
        to_ascii(&cps, &mut out)?;
        Ok(alloc::string::String::from_utf8(out.into_inner()).unwrap())
    }

    #[test]
    fn uts46() {
        assert_eq!(ascii("bücher.test").unwrap(), "xn--bcher-kva.test");
        assert_eq!(ascii("BÜCHER.TEST").unwrap(), "xn--bcher-kva.test");
        assert_eq!(ascii("faß.test").unwrap(), "xn--fa-hia.test");
        assert_eq!(ascii("bücher\u{3002}test").unwrap(), "xn--bcher-kva.test");
        assert_eq!(ascii("Ⅻ.test").unwrap(), "xii.test");
        assert_eq!(ascii("a\u{ad}b.test").unwrap(), "ab.test");
        assert_eq!(ascii("a_bé.test").unwrap(), "xn--a_b-dma.test");
        assert_eq!(ascii("שלום.test").unwrap(), "xn--9dbne9b.test");
        assert_eq!(ascii("ꞵ.test").unwrap(), "xn--968a.test");
        assert_eq!(ascii("ü").unwrap(), "xn--tda");
        assert_eq!(ascii("\u{915}\u{94d}\u{200d}.test").unwrap(), "xn--11b6iy14e.test");
        assert!(ascii("a\u{200d}b.test").is_err());
        assert!(ascii("a\u{200c}b.test").is_err());
        assert!(ascii("ab--cdé.test").is_err());
        assert!(ascii("-bücher.test").is_err());
        assert!(ascii("aש.test").is_err());
        assert!(ascii("😀.test").is_err());
        assert!(ascii("\u{301}a.test").is_err());
        assert!(ascii(&("a".repeat(63) + "é.test")).is_err());
        assert_eq!(ascii("bücher..test").unwrap(), "xn--bcher-kva..test");
        // RFC 5893 rule 4: European and Arabic-Indic digits together (a deliberate difference).
        assert!(ascii("\u{644}\u{660}\u{6f0}.test").is_err());
    }

    #[test]
    fn unicode() {
        let mut out = TryVec::new();
        to_unicode(b"XN--BCHER-KVA.xn--zz-.xn--fa-hia", &mut out).unwrap();
        let s: alloc::string::String = out.iter().map(|&c| char::from_u32(c).unwrap()).collect();
        assert_eq!(s, "BüCHER.xn--zz-.faß");
    }

    // ---- table-level equivalence tests (COLD-TABLE-IDNA): independent of the table form ----

    fn spec_dir() -> std::path::PathBuf {
        std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../spec/unicode/15.1.0")
    }

    /// Every code point's status, IDNA2008 flag and mapping equal the pinned `IdnaMappingTable.txt`.
    #[test]
    fn mapping_matches_public_table() {
        let text = std::fs::read_to_string(spec_dir().join("IdnaMappingTable.txt")).unwrap();
        let mut seen = 0u32;
        for line in text.lines() {
            let line = line.split('#').next().unwrap().trim();
            if line.is_empty() {
                continue;
            }
            let f: alloc::vec::Vec<&str> = line.split(';').map(str::trim).collect();
            let (a, b) = match f[0].split_once("..") {
                Some((a, b)) => (u32::from_str_radix(a, 16).unwrap(), u32::from_str_radix(b, 16).unwrap()),
                None => (u32::from_str_radix(f[0], 16).unwrap(), u32::from_str_radix(f[0], 16).unwrap()),
            };
            let code = match f[1] {
                "valid" => VALID,
                "ignored" => IGNORED,
                "mapped" => MAPPED,
                "deviation" => DEVIATION,
                "disallowed" => 4,
                "disallowed_STD3_valid" => STD3_VALID,
                "disallowed_STD3_mapped" => STD3_MAPPED,
                other => panic!("status {other}"),
            };
            let map: alloc::vec::Vec<u32> =
                f.get(2).map_or(alloc::vec::Vec::new(), |m| m.split_whitespace().map(|x| u32::from_str_radix(x, 16).unwrap()).collect());
            let excl = if f.get(3).is_some_and(|x| !x.is_empty()) { EXCLUDED } else { 0 };
            for c in a..=b {
                let s = status(c);
                let m = mapping(c);
                assert_eq!(s, code | excl, "status of {c:04X}");
                if !map.is_empty() {
                    assert_eq!(&*m, map.as_slice(), "mapping of {c:04X}");
                } else {
                    assert!(m.is_empty(), "mapping of {c:04X}");
                }
                seen += 1;
            }
        }
        // Every code point is covered by the file (it lists all of 0..=10FFFF).
        assert_eq!(seen, 0x11_0000);
    }

    /// Bidi class, combining mark and joining type against UnicodeData.txt / ArabicShaping.txt.
    #[test]
    fn properties_match_public_data() {
        let ud = std::fs::read_to_string(spec_dir().join("UnicodeData.txt")).unwrap();
        let mut first = 0u32;
        let mut listed = std::collections::BTreeSet::new();
        for line in ud.lines() {
            let f: alloc::vec::Vec<&str> = line.split(';').collect();
            let cp = u32::from_str_radix(f[0], 16).unwrap();
            let lo = if f[1].ends_with(", Last>") { first } else { cp };
            if f[1].ends_with(", First>") {
                first = cp;
                continue;
            }
            let code = match f[4] {
                "L" => 0,
                "R" => 1,
                "AL" => 2,
                "EN" => 3,
                "ES" => 4,
                "ET" => 5,
                "AN" => 6,
                "CS" => 7,
                "NSM" => 8,
                "BN" => 9,
                "ON" => 10,
                _ => 11,
            };
            for c in lo..=cp {
                listed.insert(c);
                assert_eq!(bidi(c), code, "bidi of {c:04X}");
                assert_eq!(is_mark(c), f[2].starts_with('M'), "mark of {c:04X}");
            }
        }
        // Shaping: R/D/L/C letters are listed in ArabicShaping.txt; T is Mn, Me, Cf.
        let ar = std::fs::read_to_string(spec_dir().join("ArabicShaping.txt")).unwrap();
        for line in ar.lines() {
            let line = line.split('#').next().unwrap().trim();
            if line.is_empty() {
                continue;
            }
            let f: alloc::vec::Vec<&str> = line.split(';').map(str::trim).collect();
            let c = u32::from_str_radix(f[0], 16).unwrap();
            let want = match f[2] {
                "L" => 2,
                "R" => 3,
                "D" => 4,
                "T" => 1,
                _ => continue,
            };
            assert_eq!(joining_of(c), want, "joining type of {c:04X}");
        }
    }

    fn fnv(h: &mut u64, v: u64) {
        *h ^= v;
        *h = h.wrapping_mul(0x0100_0000_01b3);
    }

    /// A digest of every table-backed lookup over all code points, taken from the original
    /// table form: any difference in the redesigned tables is a difference in behaviour.
    #[test]
    fn lookup_digest_over_all_code_points() {
        let mut h: u64 = 0xcbf2_9ce4_8422_2325;
        let bases = [0x61u32, 0x65, 0x6f, 0x75, 0x4e, 0x1100, 0x1161, 0xac00, 0x915, 0x627, 0x3b1];
        for c in 0..0x11_0000u32 {
            let s = status(c);
            let m = mapping(c);
            fnv(&mut h, u64::from(c));
            fnv(&mut h, u64::from(s));
            for &x in m.iter() {
                fnv(&mut h, u64::from(x));
            }
            fnv(&mut h, 0xffff_ffff);
            fnv(&mut h, u64::from(bidi(c)));
            fnv(&mut h, u64::from(joining_of(c)));
            fnv(&mut h, u64::from(is_mark(c)));
            let mut d = TryVec::new();
            decompose(c, &mut d).unwrap();
            for &x in d.iter() {
                fnv(&mut h, u64::from(x));
            }
            fnv(&mut h, 0xffff_fffe);
            for &x in nfc(d.as_slice()).unwrap().iter() {
                fnv(&mut h, u64::from(x));
            }
            fnv(&mut h, 0xffff_fffd);
            for &b in &bases {
                for &x in nfc(&[b, c]).unwrap().iter() {
                    fnv(&mut h, u64::from(x));
                }
                fnv(&mut h, 0xffff_fffc);
            }
        }
        assert_eq!(h, DIGEST, "lookup digest (update only for a deliberate table change)");
    }


    /// Taken from the original table form, then re-pinned once: the redesigned table keeps the public
    /// mapping of the two deviation code points that have one (U+00DF -> "ss", U+03C2 -> U+03C3), which the
    /// original dropped because nontransitional processing never applies it. Nothing else differs.
    const DIGEST: u64 = 13_148_791_111_395_200_277;
}
